import{_ as i,o as t,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"The ‘Scrub-Type to Limitations’ Matrix - Ronen Friedman, IBM","description":"","frontmatter":{"title":"The ‘Scrub-Type to Limitations’ Matrix - Ronen Friedman, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Scrub","Distributed Storage","Configuration","Performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/The_Scrub-Type_to_Limitations_Matrix_-_Ronen_Friedman_IBM.md","filePath":"posts/2025/The_Scrub-Type_to_Limitations_Matrix_-_Ronen_Friedman_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2025/The_Scrub-Type_to_Limitations_Matrix_-_Ronen_Friedman_IBM.md"};function n(o,r,u,c,s,b){return t(),e("div",null,[...r[0]||(r[0]=[l('<p>在这次Ceph技术会议的最后时段，Ronan Friedman，Ceph Scrub代码维护者，分享了关于Ceph Scrub配置选项及其限制的讨论。以下是对会议内容的总结和改进：</p><h3 id="会议纪要-ceph-scrub配置与限制讨论" tabindex="-1">会议纪要：Ceph Scrub配置与限制讨论 <a class="header-anchor" href="#会议纪要-ceph-scrub配置与限制讨论" aria-label="Permalink to &quot;会议纪要：Ceph Scrub配置与限制讨论&quot;">​</a></h3><p><strong>会议时间</strong>：某次Ceph技术会议的最后时段</p><p><strong>主讲人</strong>：Ronan Friedman，Ceph Scrub代码维护者，过去五年专注于该领域。</p><p><strong>会议主题</strong>：Ceph Scrub的配置选项及其对不同类型Scrub的影响，特别是在Tentacle版本中的改进。</p><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>Scrub类型及其优先级</strong>：</p><ul><li>Scrub类型分为六种，按优先级递增排列，包括： <ul><li>周期性Scrub（Periodic Scrub）</li><li>操作员请求的Scrub（Operator Requested Scrub）</li><li>修复后Scrub（After Repair Scrub）</li><li>修复Scrub（Repair Scrub）</li><li>大规模Scrub（Mass Scrub）</li></ul></li><li>操作员请求的Scrub优先级最高，几乎总是会被执行，除非PG状态不允许。</li></ul></li><li><p><strong>Scrub的限制条件</strong>：</p><ul><li><strong>时间限制</strong>：通过配置选项限制Scrub在特定时间段内执行。</li><li><strong>CPU负载限制</strong>：当CPU负载过高时，Scrub会被延迟或暂停。</li><li><strong>副本资源预留</strong>：每个OSD会统计参与的Scrub数量，达到OSD Max Scrubs时，新的Scrub请求会被排队。</li><li><strong>最大并发Scrub数</strong>：每个OSD作为Primary时，不会启动超过OSD Max Concurrency的Scrub。</li></ul></li><li><p><strong>Tentacle版本中的改进</strong>：</p><ul><li><strong>修复Scrub</strong>：修复Scrub会忽略大多数限制条件，确保修复后的数据一致性检查。</li><li><strong>大规模Scrub</strong>：主要用于新PG的首次Scrub，优先级较低，遵循大多数限制。</li><li><strong>内部过期机制的移除</strong>：Tentacle版本中移除了内部过期机制，仅保留健康警告。</li></ul></li><li><p><strong>Scrub调度机制的改进</strong>：</p><ul><li>浅Scrub和深Scrub的调度机制被分离，避免了相互影响。</li><li>操作员可以通过配置参数控制深Scrub的调度间隔和随机化因子。</li></ul></li><li><p><strong>CPU负载限制的保留</strong>：</p><ul><li>CPU负载限制仍然保留，但可以通过设置高阈值来忽略该限制。</li><li>在Crimson调度器中，CPU负载显示为100%，但实际Scrub对CPU的影响较小。</li></ul></li><li><p><strong>未来改进方向</strong>：</p><ul><li>主讲人呼吁社区反馈，特别是关于Scrub性能和调优的需求。</li><li>Yit团队正在计划在下一个Ceph版本中引入Scrub相关的性能计数器。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续保留CPU负载限制，但允许通过配置高阈值来忽略该限制。</li><li>移除内部过期机制，简化Scrub调度逻辑。</li><li>社区反馈将用于进一步优化Scrub性能和调度机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Yit团队将在下一个Ceph版本中引入Scrub性能计数器。</li><li>主讲人将继续收集社区反馈，特别是关于Scrub调优和性能改进的需求。</li></ul><p><strong>会议总结</strong>：本次会议详细讨论了Ceph Scrub的配置选项及其在Tentacle版本中的改进，特别是如何通过配置限制Scrub对集群性能的影响。会议还呼吁社区提供更多关于Scrub性能的反馈，以便进一步优化。</p>',12)])])}const _=i(a,[["render",n]]);export{p as __pageData,_ as default};
